(function () {
'use strict';
var Utils = window.Utils;
var HttpApi = window.HttpApi;
function positionOf(store) {
var pos = store.position;
if (typeof pos === 'string') {
try { pos = JSON.parse(pos); } catch (e) { pos = null; }
}
if (!pos || typeof pos !== 'object') return null;
var lat = Number(pos.latitude !== undefined ? pos.latitude : pos.lat);
var lng = Number(pos.longitude !== undefined ? pos.longitude : pos.lng);
return isFinite(lat) && isFinite(lng) ? { lat: lat, lng: lng } : null;
}
function weekText(businessHours) {
if (!businessHours) return '';
if (typeof businessHours === 'string') return businessHours;
if (Array.isArray(businessHours)) {
return businessHours.map(function (item) {
if (typeof item === 'string') return item;
return [item.day || item.week, item.start || item.open, item.end || item.close].filter(Boolean).join(' ');
}).filter(Boolean).join('；');
}
return '';
}
function render(store) {
var hero = document.getElementById('store-hero');
var pos = positionOf(store);
var logo = Utils.thumb(store.logo, 160, 160);
var mapUrl = pos
? 'https://uri.amap.com/marker?position=' + pos.lng + ',' + pos.lat +
'&name=' + encodeURIComponent(store.name || '店铺') +
'&src=store.fangkelianmeng.com&coordinate=gaode&callnative=1'
: '';
var actions = [];
if (store.phone) {
actions.push('<a class="btn btn-primary btn-sm" href="tel:' + Utils.escapeHtml(store.phone) + '">拨打电话</a>');
}
if (mapUrl) {
actions.push('<a class="btn btn-outline btn-sm" href="' + Utils.escapeHtml(mapUrl) + '" target="_blank" rel="noopener noreferrer">前往店铺</a>');
}
if (store.wechat) {
actions.push('<button type="button" class="btn btn-outline btn-sm" id="store-copy-wechat">复制微信</button>');
}
hero.innerHTML = [
'<div class="store-card" style="border:0;padding:0;box-shadow:none;background:transparent">',
'<span class="store-logo" style="width:88px;height:88px">' + (logo
? '<img src="' + Utils.escapeHtml(logo) + '" alt="' + Utils.escapeHtml(store.name || '店铺') + '">'
: '<span class="store-logo-empty">店</span>') + '</span>',
'<span class="store-info">',
'<span class="store-name" style="font-size:20px">' + Utils.escapeHtml(store.name || '未命名店铺') + '</span>',
'<span class="store-meta">' +
(store.city ? '<span class="tag">' + Utils.escapeHtml(store.city) + '</span>' : '') +
(store.category ? '<span class="tag">' + Utils.escapeHtml(store.category) + '</span>' : '') +
'</span>',
store.subtitle ? '<span class="store-sub">' + Utils.escapeHtml(store.subtitle) + '</span>' : '',
store.address ? '<span class="store-meta">地址 ' + Utils.escapeHtml(store.address) + '</span>' : '',
store.phone ? '<span class="store-meta">电话 ' + Utils.escapeHtml(store.phone) + '</span>' : '',
'</span>',
'</div>',
actions.length ? '<div class="form-actions">' + actions.join('') + '</div>' : ''
].join('');
if (store.wechat) {
var btn = document.getElementById('store-copy-wechat');
if (btn) {
btn.addEventListener('click', function () {
Utils.copyText(store.wechat).then(function (ok) {
Utils.toast(ok ? '微信号已复制' : '复制失败，请手动记录：' + store.wechat);
});
});
}
}
var descBox = document.getElementById('store-about');
var desc = store.describe || store.desc || '';
if (desc) {
descBox.hidden = false;
document.getElementById('store-desc').innerHTML = Utils.sanitizeHtml(desc);
}
var hoursText = weekText(store.business_hours);
var mainBusiness = Array.isArray(store.main_business) ? store.main_business.filter(Boolean) : [];
var rows = [];
if (hoursText) rows.push('<dl class="spec-item"><dt>营业时间</dt><dd>' + Utils.escapeHtml(hoursText) + '</dd></dl>');
if (mainBusiness.length) rows.push('<dl class="spec-item"><dt>主营业务</dt><dd>' + Utils.escapeHtml(mainBusiness.join('、')) + '</dd></dl>');
if (store.email) rows.push('<dl class="spec-item"><dt>邮箱</dt><dd>' + Utils.escapeHtml(store.email) + '</dd></dl>');
if (rows.length) {
document.getElementById('store-hours').hidden = false;
document.getElementById('store-hours-grid').innerHTML = rows.join('');
}
Utils.setSeo({
title: (store.name || '店铺信息') + ' - 东北电动车汇',
description: Utils.truncate(store.describe || store.subtitle || (store.name + '，地址：' + (store.address || '')), 110),
canonical: location.origin + location.pathname + '?id=' + encodeURIComponent(store._id || '')
});
}
function loadStore(id) {
return HttpApi.store.getDetail({ id: id }).then(function (res) {
var store = res && res.code === 0 ? res.data : null;
if (store && store._id) {
render(store);
return true;
}
return false;
});
}
function init() {
var id = Utils.query('id');
Utils.track('store_detail_view', { id: id });
if (id) {
loadStore(id).then(function (ok) {
if (!ok) showEmpty();
});
return;
}
HttpApi.store.getList({ pageIndex: 1, pageSize: 1 }).then(function (res) {
var row = res && res.rows && res.rows[0];
if (row && row._id) {
loadStore(row._id).then(function (ok) {
if (!ok) showEmpty();
});
} else {
showEmpty();
}
});
}
function showEmpty() {
document.getElementById('store-hero').innerHTML = Utils.emptyHtml(
'店铺不存在或已下架',
'<a class="btn btn-outline btn-sm" href="/shop/city.html">同城找店</a>'
);
}
if (document.readyState === 'loading') {
document.addEventListener('DOMContentLoaded', init);
} else {
init();
}
})();
